#include <iostream>
#include <vector>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    long long s;
    if (!(cin >> n >> s)) return 0;

    vector<int> freq(1000001, 0);
    freq[0] = 1;

    long long current_sum = 0;
    long long ans = 0;

    for (int i = 0; i < n; ++i) {
        int x;
        cin >> x;
        current_sum += x;

        if (current_sum >= s) {
            ans += freq[current_sum - s];
        }

        freq[current_sum]++;
    }

    cout << ans << "\n";

    return 0;
}
